-- Text of the explanatory memorandum (expunerea de motive) of a bill, and its plain-language summary.

-- `text` is NULL when the PDF has no text layer (scanned): it is then not fetched again and not summarised.
CREATE TABLE bill_texts (
    bill_id    text PRIMARY KEY REFERENCES bills (id) ON DELETE CASCADE,
    url        text NOT NULL,
    text       text,
    fetched_at timestamptz NOT NULL DEFAULT now()
);

-- Generated by a local open-weight language model (ADR 0006); shown labelled, with the source document.
CREATE TABLE bill_summaries (
    bill_id      text PRIMARY KEY REFERENCES bills (id) ON DELETE CASCADE,
    summary      text NOT NULL,
    model        text NOT NULL,
    source_url   text NOT NULL,
    generated_at timestamptz NOT NULL DEFAULT now()
);
